<?php
declare(strict_types=1);
final class ThesisService
{
    public function create(array $data): int { Validator::required($data,['student_id'=>'الطالب','title'=>'عنوان الرسالة','start_date'=>'تاريخ البداية']);$r=new ThesisRepository();$sid=(int)$data['student_id'];if($r->studentHasThesis($sid))throw new InvalidArgumentException('لدى الطالب رسالة علمية مفتوحة بالفعل.');if(!empty($data['proposal_id'])){ $p=Database::connection()->prepare("SELECT status,student_id FROM research_proposals WHERE id=?");$p->execute([(int)$data['proposal_id']]);$pr=$p->fetch();if(!$pr||$pr['student_id']!=$sid||$pr['status']!=='APPROVED')throw new InvalidArgumentException('يجب اختيار مقترح بحث معتمد لنفس الطالب.');}$id=$r->create([$sid,($data['proposal_id']??'')===''?null:(int)$data['proposal_id'],trim($data['title']),$data['start_date']]);audit('CREATE','thesis',$id);return $id; }
    public function status(int $id,string $status): void { $allowed=['ACTIVE','READY_FOR_DEFENSE','DEFENDED','CANCELLED'];if(!in_array($status,$allowed,true))throw new InvalidArgumentException('حالة الرسالة غير صالحة.');$r=new ThesisRepository();$row=$r->find($id);if(!$row)throw new InvalidArgumentException('الرسالة غير موجودة.');$role=current_user()['role']??'';if($role==='SUPERVISOR'){ $q=Database::connection()->prepare('SELECT 1 FROM student_supervisors ss JOIN supervisors sv ON sv.id=ss.supervisor_id WHERE ss.student_id=? AND sv.user_id=?');$q->execute([(int)$row['student_id'],(int)current_user()['id']]);if(!$q->fetchColumn())throw new RuntimeException('لا يمكنك تعديل رسالة ليست تحت إشرافك.'); }
        $trans=['ACTIVE'=>['READY_FOR_DEFENSE','CANCELLED'],'READY_FOR_DEFENSE'=>['ACTIVE','CANCELLED'],'DEFENDED'=>[],'CANCELLED'=>['ACTIVE'],'GRADUATED'=>[]];if($status!==$row['status']&&!in_array($status,$trans[$row['status']]??[],true))throw new InvalidArgumentException('انتقال حالة الرسالة غير مسموح.');if($status==='DEFENDED'){$q=Database::connection()->prepare("SELECT result FROM defenses WHERE thesis_id=? ORDER BY id DESC LIMIT 1");$q->execute([$id]);$res=$q->fetchColumn();if(!in_array($res,['PASS','PASS_WITH_CHANGES'],true))throw new InvalidArgumentException('لا يمكن جعل الرسالة مناقشة إلا بعد نتيجة نجاح.');}$r->setStatus($id,$status);audit('STATUS','thesis',$id,['from'=>$row['status'],'to'=>$status]); }
}
